mapper.select:
SELECT TRANSFER_ID as "transferId", TRANSFER_NO as "transferNo", TRANSFER_PERIOD as "transferPeriod", TRANSFER_TYPE as "transferType", TRANSFER_TYPE_NAME as "transferTypeName", INVENTORY_COUNT as "inventoryCount", TRANSFER_AMOUNT as "transferAmount", VARIANCE_AMOUNT as "varianceAmount", TRANSFER_STATUS as "transferStatus", CASE TRANSFER_STATUS WHEN 0 THEN 'PENDING' WHEN 1 THEN 'TRANSFERRED' WHEN 2 THEN 'REVOKED' ELSE 'UNKNOWN' END as "status", VOUCHER_COUNT as "voucherCount", VOUCHER_IDS as "voucherIds", TO_CHAR(TRANSFER_TIME, 'YYYY-MM-DD HH24:MI:SS') as "transferTime", DESCRIPTION as "description", CREATOR_ID as "operatorName", TO_CHAR(CREATE_TIME, 'YYYY-MM-DD HH24:MI:SS') as "createTime", TO_CHAR(UPDATE_TIME, 'YYYY-MM-DD HH24:MI:SS') as "updateTime" FROM TBL_COST_TRANSFER WHERE DELETED = 0 AND TENANT_ID = #{param.tenantId}
AND TRANSFER_PERIOD = #{param.transferPeriod}
AND TRANSFER_TYPE = #{param.transferType}
AND EXISTS ( SELECT 1 FROM TBL_COST_TRANSFER_DETAIL d INNER JOIN TBL_INVENTORY_MASTER m ON d.INVENTORY_ID = m.INVENTORY_ID WHERE d.TRANSFER_ID = TBL_COST_TRANSFER.TRANSFER_ID AND m.CATEGORY_ID = #{param.categoryId} )
AND CASE TRANSFER_STATUS WHEN 0 THEN 'PENDING' WHEN 1 THEN 'TRANSFERRED' WHEN 2 THEN 'REVOKED' END = #{param.status}
ORDER BY CREATE_TIME DESC

SELECT * FROM TBL_COST_TRANSFER
WHERE TRANSFER_NO = #{transferNo}
AND TENANT_ID = #{tenantId}
AND DELETED = 0

mapper.update:
UPDATE TBL_COST_TRANSFER SET TRANSFER_STATUS = #{transferStatus}, TRANSFER_TIME = SYSDATE, UPDATER_ID = #{updaterId}, UPDATE_TIME = SYSDATE WHERE TRANSFER_ID IN
#{transferId}
AND DELETED = 0

UPDATE TBL_COST_TRANSFER SET TRANSFER_STATUS = 2, UPDATER_ID = #{updaterId}, UPDATE_TIME = SYSDATE WHERE TRANSFER_ID IN
#{transferId}
AND DELETED = 0

mapper.select:
SELECT NVL(SUM(CASE WHEN TRANSFER_STATUS = 0 THEN 1 ELSE 0 END), 0) as pendingCount, NVL(SUM(CASE WHEN TRANSFER_STATUS = 1 THEN 1 ELSE 0 END), 0) as transferredCount, NVL(SUM(CASE WHEN TRANSFER_STATUS = 1 THEN TRANSFER_AMOUNT ELSE 0 END), 0) as totalAmount, NVL(SUM(CASE WHEN TRANSFER_STATUS = 1 THEN VARIANCE_AMOUNT ELSE 0 END), 0) as varianceAmount FROM TBL_COST_TRANSFER WHERE DELETED = 0 AND TENANT_ID = #{param.tenantId}
AND TRANSFER_PERIOD = #{param.transferPeriod}
AND TRANSFER_TYPE = #{param.transferType}
AND EXISTS ( SELECT 1 FROM TBL_COST_TRANSFER_DETAIL d INNER JOIN TBL_INVENTORY_MASTER m ON d.INVENTORY_ID = m.INVENTORY_ID WHERE d.TRANSFER_ID = TBL_COST_TRANSFER.TRANSFER_ID AND m.CATEGORY_ID = #{param.categoryId} )
AND CASE TRANSFER_STATUS WHEN 0 THEN 'PENDING' WHEN 1 THEN 'TRANSFERRED' WHEN 2 THEN 'REVOKED' END = #{param.status}
